const YASEI_LAST_BOSS_PATTERNS = [
  'yasei no last boss ga arawareta',
  'a wild last boss appeared',
];

const SEASON_2_ANIME_PATTERNS = [
  'tougen anki nikko kegon no taki hen',
  'tougen anki nikkou kegon no taki hen',
  ...YASEI_LAST_BOSS_PATTERNS,
  'koori no jouheki',
  'hotel inhumans',
];

const TRAILING_SUBTITLE_SUFFIX_REGEX =
  /[._-](?:ass|srt|ssa|vtt|sub|translated|burmese|myanmar|mm|clean|fixed|edited|final|forced|sdh|cc|hi|signs?|songs?|dialogue|full|default|commentary|track\d*|sub\d*|jpn|jap|ja|jp|eng|en|en-us|en-gb|bur|mya|my|chi|zho|zh|zh-cn|zh-tw|zh-hk|chs|cht|kor|ko|spa|es|es-la|es-419|fra|fre|fr|deu|ger|de|ita|it|por|pt|pt-br|rus|ru|ara|ar|ind|id|msa|may|ms|tha|th|vie|vi|pol|pl|tur|tr|nld|dut|nl|swe|sv|fin|fi|nor|no|dan|da|ces|cze|cs|hun|hu|ron|rum|ro|ukr|uk|heb|he|hin|und|mul|orig|raw)(?:\s*\(\d+\))?$/i;

/**
 * Strips chained trailing subtitle extensions, language codes (e.g. .jpn, .eng, .en-US),
 * and output tags (e.g. .translated, .forced, .sdh) from the end of a filename.
 */
function stripTrailingSubtitleSuffixes(fileName: string): string {
  let base = (fileName || '').trim();
  while (base.length > 0) {
    const next = base.replace(TRAILING_SUBTITLE_SUFFIX_REGEX, '').trim();
    if (next === base) break;
    base = next;
  }
  return base;
}

/**
 * Determines whether the uploaded file belongs to an anime that should show "Season 2".
 */
export function detectSeasonNumber(fileName: string): number {
  const normalized = stripTrailingSubtitleSuffixes(fileName)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!normalized) return 1;
  return SEASON_2_ANIME_PATTERNS.some((title) => normalized.includes(title)) ? 2 : 1;
}

/**
 * Extracts episode number from anime subtitle filenames such as:
 * - "[Erai-raws] Tank Chair - 08 [1080p AMZN WEB-DL AVC EAC3][MultiSub][D86EA8EA].jpn.translated.ass" -> "8"
 * - "[Erai-raws] Koori no Jouheki 2nd Season - 07 [1080p...].ass" -> "7"
 * - "[Erai-raws] jukishi - 20 [1080p...].ass" -> "20"
 * - "Anime S02E03 [1080p].ass" -> "3"
 * - "Tougen Anki - Nikko Kegon no Taki-hen - 12v2.srt" -> "12"
 * - "Yasei no Last Boss ga Arawareta! - 13 [1080p].ass" -> "1" (Season 2 Ep 1; 21 -> Ep 9)
 */
export function extractEpisodeNumber(fileName: string): string {
  const base = stripTrailingSubtitleSuffixes(fileName);

  if (!base) return '1';

  const normalizedTitle = base
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const isYaseiLastBoss = YASEI_LAST_BOSS_PATTERNS.some((p) => normalizedTitle.includes(p));

  const formatEp = (raw: string): string => {
    const cleaned = raw.replace(/^0+(?=\d)/, '') || '1';
    if (isYaseiLastBoss) {
      const parsedNum = Number(cleaned);
      if (Number.isFinite(parsedNum) && parsedNum >= 13 && parsedNum <= 24) {
        return String(Number((parsedNum - 12).toFixed(2)));
      }
    }
    return cleaned;
  };

  // 1. Explicit S02E07 / Episode 07 / Ep 07 / 第07話 / E07 markers
  const explicitMatch = base.match(
    /(?:^|[^a-z0-9])(?:S\d{1,2}\s*E|Episode|Ep\.?)\s*0*(\d{1,4}(?:\.\d+)?)(?=[^a-z0-9]|v\d|$)/i
  );
  if (explicitMatch) {
    return formatEp(explicitMatch[1]);
  }

  const jpExplicitMatch = base.match(/第\s*0*(\d{1,4}(?:\.\d+)?)\s*話/);
  if (jpExplicitMatch) {
    return formatEp(jpExplicitMatch[1]);
  }

  // Strip bracketed/parenthetical release metadata like [1080p], [MultiSub], [D86EA8EA], (WEB), then any newly exposed .jpn/.eng suffixes
  const withoutBrackets = stripTrailingSubtitleSuffixes(
    base
      .replace(/\[[^\]]*\]/g, ' ')
      .replace(/\([^)]*\)/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
  );

  // 2. Standard fansub separator " - 08", " - 08v2", or " - 08 - Episode Title" (after removing [tags] & .jpn)
  const dashMatches = [
    ...withoutBrackets.matchAll(/(?:^|\s)[-\u2013\u2014]\s*0*(\d{1,4}(?:\.\d+)?)(?:v\d+)?(?=\s*(?:[-\u2013\u2014:\.]|END|FINAL|$))/gi),
  ];
  if (dashMatches.length > 0) {
    return formatEp(dashMatches[dashMatches.length - 1][1]);
  }

  // 2.5 Hash-prefixed episode numbers (#8 / #08) or standalone scene-style 2-3 digit E08
  const hashOrSceneEMatch = withoutBrackets.match(/(?:^|[\s._-])(?:#0*(\d{1,3}(?:\.\d+)?)|E0*(\d{2,3}(?:\.\d+)?))(?:v\d+)?(?=$|[\s._-])/i);
  if (hashOrSceneEMatch) {
    return formatEp(hashOrSceneEMatch[1] || hashOrSceneEMatch[2]);
  }

  // 3. Fallback: remove resolution/codec/source/season markers, then match trailing episode number
  const cleanedForTrailing = withoutBrackets
    .replace(
      /\b(?:\d{3,4}p|x26[45]|h\.?26[45]|hevc|avc|aac(?:\d+(?:\.\d+)?)?|eac3|ac3|ddp(?:\d+(?:\.\d+)?)?|flac|opus|10bit|8bit|web-?dl|webrip|bluray|bdrip|dvdrip|hdtv|amzn|nf|cr|baha|bilibili|hidive|multisub|multi|dual[.\s_-]?audio|proper|repack|season\s*\d+|\d+(?:st|nd|rd|th)\s+season)\b/gi,
      ' '
    )
    .replace(/[._\s]+/g, ' ')
    .trim();

  const trailingMatch = cleanedForTrailing.match(/(?:^|[\s._#-])0*(\d{1,3}(?:\.\d+)?)(?:v\d+)?(?:\s*(?:END|FINAL))?$/i);
  if (trailingMatch) {
    return formatEp(trailingMatch[1]);
  }

  return '1';
}

/**
 * Finds the Start timestamp of the very first visible subtitle line (any style/type: Dialogue, Flashback,
 * Sign, Title, Narration, Lyrics — skipping Comments, watermark lines, and empty/drawing lines)
 * to use as the End timestamp for CreditStyle and MarqueeStyle.
 */
export function getFirstSpokenDialogueStart(events: AssEvent[]): string {
  let bestStart: string | null = null;
  let bestSeconds = Number.POSITIVE_INFINITY;

  for (const e of events) {
    if (e.type !== 'Dialogue' || !e.isTranslatable) continue;
    const styleLower = (e.style || '').trim().toLowerCase();
    if (
      styleLower === '13' ||
      styleLower === 'episode' ||
      styleLower === 'creditstyle' ||
      styleLower === 'marqueestyle'
    ) {
      continue;
    }
    const visible = (e.text || '').replace(/\{[^}]*\}/g, '').replace(/\\[Nnh]/g, '').trim();
    if (!visible) continue;

    const secs = parseAssTimeToSeconds(e.start);
    if (secs > 0 && secs < bestSeconds) {
      bestSeconds = secs;
      bestStart = e.start;
    }
  }

  return bestStart || '0:00:10.00';
}

/**
 * Checks whether the parsed subtitle events already contain the NaJu Anime 4-line header block.
 */
export function hasWatermarkEvents(events: AssEvent[]): boolean {
  return events.some(
    (e) =>
      (e.style === '13' && e.text.includes('NaJu Anime')) ||
      (e.style === 'MarqueeStyle' && e.text.includes('NaJu_NewAnime'))
  );
}

/**
 * Generates the 4 standard NaJu Anime header Dialogue lines tailored to the file's
 * season, episode number, and first spoken dialogue start timestamp.
 */
export function buildWatermarkEvents(fileName: string, events: AssEvent[]): AssEvent[] {
  const season = detectSeasonNumber(fileName);
  const episode = extractEpisodeNumber(fileName);
  const creditEnd = getFirstSpokenDialogueStart(events);

  const makeEvent = (index: number, layer: string, start: string, end: string, style: string, text: string): AssEvent => ({
    index,
    type: 'Dialogue',
    layer,
    start,
    end,
    style,
    name: '',
    marginL: '0',
    marginR: '0',
    marginV: '0',
    effect: '',
    text,
    originalText: text,
    isTranslatable: false,
  });

  return [
    makeEvent(
      -4,
      '0',
      '0:00:00.00',
      '0:28:56.98',
      '13',
      '{\\an2\\blur0.3\\fc&H2C3DEA&\\frx89\\t(19,23371,\\frx0)\\\\pos(618.667,10.667)}NaJu Anime'
    ),
    makeEvent(
      -3,
      '1',
      '0:00:00.50',
      '0:00:10.00',
      'Episode',
      `{\\fad(1000,1000)\\pos(1.6,0.667)}{\\c&H00FFFF&}Season ${season} - {\\c&HFFFFFF&}Episode ${episode}{\\c&H00FF00&}{\\c&HFFFFFF&}`
    ),
    makeEvent(
      -2,
      '2',
      '0:00:00.00',
      creditEnd,
      'CreditStyle',
      '{\\fad(1000,1000)\\pos(317.333,296.889)}TLC & Encoder : {\\c&H00D7FF&}NaJu'
    ),
    makeEvent(
      -1,
      '3',
      '0:00:00.00',
      creditEnd,
      'MarqueeStyle',
      '{\\fad(1000,1000)\\pos(317.333,318)}{\\c&HFFFF00&}https://t.me/NaJu_NewAnime'
    ),
  ];
}

const TARGET_PLAY_RES_X = 640;
const TARGET_PLAY_RES_Y = 360;

function formatAssNum(value: number, maxDecimals = 3): string {
  if (!Number.isFinite(value)) return '0';
  const rounded = Number(value.toFixed(maxDecimals));
  return Object.is(rounded, -0) ? '0' : String(rounded);
}

/**
 * Scales ASS vector drawing coordinate pairs (m, n, l, b, s, p, c).
 */
function scaleAssDrawingCommands(drawing: string, scaleX: number, scaleY: number): string {
  let expectX = true;
  return drawing.replace(/([a-zA-Z])|(-?\d+(?:\.\d+)?)/g, (token, cmd: string | undefined, numStr: string | undefined) => {
    if (cmd) {
      expectX = true;
      return cmd;
    }
    const num = parseFloat(numStr!);
    const scaled = expectX ? num * scaleX : num * scaleY;
    expectX = !expectX;
    return formatAssNum(scaled, 2);
  });
}

/**
 * Scales an ASS Style line's pixel dimensions (Fontsize, Spacing, Outline, Shadow, Margins)
 * from the source PlayRes to the unified 640x360 target PlayRes.
 */
function scaleAssStyleLine(styleLine: string, formatFields: string[], scaleX: number, scaleY: number): string {
  const colonIdx = styleLine.indexOf(':');
  if (colonIdx === -1) return styleLine;
  const prefix = styleLine.slice(0, colonIdx + 1);
  const parts = styleLine.slice(colonIdx + 1).trim().split(',');
  if (parts.length < formatFields.length) return styleLine;

  const scaleField = (fieldName: string, factor: number, decimals: number) => {
    const idx = formatFields.findIndex((f) => f.toLowerCase() === fieldName.toLowerCase());
    if (idx !== -1 && idx < parts.length) {
      const val = parseFloat(parts[idx]);
      if (Number.isFinite(val)) {
        parts[idx] = formatAssNum(val * factor, decimals);
      }
    }
  };

  scaleField('Fontsize', scaleY, 2);
  scaleField('Spacing', scaleX, 2);
  scaleField('Outline', scaleY, 2);
  scaleField('Shadow', scaleY, 2);
  scaleField('MarginL', scaleX, 0);
  scaleField('MarginR', scaleX, 0);
  scaleField('MarginV', scaleY, 0);

  return `${prefix} ${parts.join(',')}`;
}

/**
 * Normalizes event inline override tags for uniform Burmese rendering at 640x360:
 * - On spoken dialogue lines, strips stray source \fs<num> overrides so every line uses
 *   the exact uniform Burmese style Fontsize (e.g. Myanmar1 = 35).
 * - On all source events (especially signs/typesets), scales coordinate and size tags
 *   (\pos, \move, \org, \clip, \iclip, \fs, \fsp, \bord, \shad, vector drawings) from
 *   the source PlayRes to 640x360.
 */
function normalizeEventTextForTargetPlayRes(
  text: string,
  scaleX: number,
  scaleY: number,
  isSign: boolean
): string {
  const needsScale = Math.abs(scaleX - 1) > 1e-4 || Math.abs(scaleY - 1) > 1e-4;
  if (!text) return text;

  let inDrawingMode = false;

  return text.replace(/(\{[^}]*\})|([^{]+)/g, (segment, tagBlock: string | undefined, plainText: string | undefined) => {
    if (plainText !== undefined) {
      if (inDrawingMode && needsScale) {
        return scaleAssDrawingCommands(plainText, scaleX, scaleY);
      }
      return plainText;
    }

    let updated = tagBlock!;

    // Track vector drawing mode {\p1}..{\p0}
    const pMatches = [...updated.matchAll(/\\p(\d+)/g)];
    if (pMatches.length > 0) {
      inDrawingMode = parseInt(pMatches[pMatches.length - 1][1], 10) > 0;
    }

    // Remove stray inline \fs<num> overrides on non-sign spoken dialogue lines for uniform font sizes
    if (!isSign) {
      updated = updated.replace(/\\fs(?![a-zA-Z])\d+(?:\.\d+)?/g, '');
      if (updated === '{}') return '';
    }

    if (!needsScale) {
      return updated;
    }

    // \pos(x,y) and \org(x,y)
    updated = updated.replace(/\\(pos|org)\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)/g, (_, tag, x, y) => {
      return `\\${tag}(${formatAssNum(parseFloat(x) * scaleX)},${formatAssNum(parseFloat(y) * scaleY)})`;
    });

    // \move(x1,y1,x2,y2[,t1,t2])
    updated = updated.replace(
      /\\move\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)([^)]*)\)/g,
      (_, x1, y1, x2, y2, rest) => {
        return `\\move(${formatAssNum(parseFloat(x1) * scaleX)},${formatAssNum(parseFloat(y1) * scaleY)},${formatAssNum(parseFloat(x2) * scaleX)},${formatAssNum(parseFloat(y2) * scaleY)}${rest})`;
      }
    );

    // \clip(...) and \iclip(...) — rectangular 4-arg or vector drawing
    updated = updated.replace(/\\(i?clip)\(([^)]*)\)/g, (_, tag, inner: string) => {
      const rectMatch = inner.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);
      if (rectMatch) {
        return `\\${tag}(${formatAssNum(parseFloat(rectMatch[1]) * scaleX)},${formatAssNum(parseFloat(rectMatch[2]) * scaleY)},${formatAssNum(parseFloat(rectMatch[3]) * scaleX)},${formatAssNum(parseFloat(rectMatch[4]) * scaleY)})`;
      }
      const vecWithScaleMatch = inner.match(/^\s*(\d+)\s*,\s*(.+)$/);
      if (vecWithScaleMatch) {
        return `\\${tag}(${vecWithScaleMatch[1]},${scaleAssDrawingCommands(vecWithScaleMatch[2], scaleX, scaleY)})`;
      }
      return `\\${tag}(${scaleAssDrawingCommands(inner, scaleX, scaleY)})`;
    });

    // \fs, \bord, \ybord, \shad, \yshad (vertical scaleY)
    updated = updated.replace(/\\(fs|bord|ybord|shad|yshad)(?![a-zA-Z])(-?\d+(?:\.\d+)?)/g, (_, tag, val) => {
      return `\\${tag}${formatAssNum(parseFloat(val) * scaleY, 2)}`;
    });

    // \fsp, \xbord, \xshad (horizontal scaleX)
    updated = updated.replace(/\\(fsp|xbord|xshad)(?![a-zA-Z])(-?\d+(?:\.\d+)?)/g, (_, tag, val) => {
      return `\\${tag}${formatAssNum(parseFloat(val) * scaleX, 2)}`;
    });

    return updated;
  });
}

/**
 * Extracts explicit PlayResX / PlayResY from parsed ASS headerSection.
 * Falls back to target 640x360 when missing so existing coordinates are not distorted.
 */
export function extractSourcePlayRes(headerSection: string[]): { playResX: number; playResY: number } {
  let rawX: number | null = null;
  let rawY: number | null = null;

  for (const line of headerSection) {
    const trimmed = line.trim();
    if (/^\[(v4\+? styles|events)\]/i.test(trimmed)) break;
    const mx = trimmed.match(/^PlayResX\s*:\s*(\d+(?:\.\d+)?)/i);
    if (mx && parseFloat(mx[1]) > 0) rawX = parseFloat(mx[1]);
    const my = trimmed.match(/^PlayResY\s*:\s*(\d+(?:\.\d+)?)/i);
    if (my && parseFloat(my[1]) > 0) rawY = parseFloat(my[1]);
  }

  if (rawX !== null && rawY !== null) {
    return { playResX: rawX, playResY: rawY };
  }
  if (rawX !== null) {
    return { playResX: rawX, playResY: rawX === 384 ? 288 : Math.round((rawX * 9) / 16) };
  }
  if (rawY !== null) {
    return { playResX: rawY === 288 ? 384 : Math.round((rawY * 16) / 9), playResY: rawY };
  }
  return { playResX: TARGET_PLAY_RES_X, playResY: TARGET_PLAY_RES_Y };
}

function stripAegisubGarbageSections(sectionLines: string[]): string[] {
  const cleaned: string[] = [];
  let skippingGarbage = false;
  for (const line of sectionLines) {
    const trimmed = line.trim();
    if (/^\[aegisub project garbage\]$/i.test(trimmed)) {
      skippingGarbage = true;
      continue;
    }
    if (skippingGarbage) {
      if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
        skippingGarbage = false;
      } else {
        continue;
      }
    }
    cleaned.push(line);
  }
  return cleaned;
}

/**
 * Builds the complete ASS subtitle file string.
 * When applyStyleMapping is true, replaces everything above [V4+ Styles] with the
 * standardized [Script Info] + [Aegisub Project Garbage] 640x360 header so every episode
 * renders identically in Aegisub 3.4.2.
 */
export function buildAss(
  parsedData: ParsedAssData,
  translatedEvents?: AssEvent[],
  applyStyleMapping = true,
  prependedEvents: AssEvent[] = [],
  signTypesetting?: SignTypesettingOptions
): string {
  const sourceEvents = translatedEvents || parsedData.events;
  const lines: string[] = [];

  let header = [...parsedData.headerSection];
  let scaleX = 1;
  let scaleY = 1;
  const sourceStyleAlignments: Record<string, number> = {};

  if (applyStyleMapping) {
    // Capture source style alignments BEFORE canonical style mapping overwrites them
    let rawStyleFields = [
      'Name', 'Fontname', 'Fontsize', 'PrimaryColour', 'SecondaryColour', 'OutlineColour', 'BackColour',
      'Bold', 'Italic', 'Underline', 'StrikeOut', 'ScaleX', 'ScaleY', 'Spacing', 'Angle',
      'BorderStyle', 'Outline', 'Shadow', 'Alignment', 'MarginL', 'MarginR', 'MarginV', 'Encoding',
    ];
    for (const hLine of header) {
      const tr = hLine.trim();
      if (/^\[events\]/i.test(tr)) break;
      if (/^Format\s*:/i.test(tr)) {
        rawStyleFields = tr.slice(tr.indexOf(':') + 1).split(',').map((f) => f.trim());
      } else if (/^Style\s*:/i.test(tr)) {
        const parts = tr.slice(tr.indexOf(':') + 1).trim().split(',');
        const nameIdx = rawStyleFields.findIndex((f) => f.toLowerCase() === 'name');
        const alignIdx = rawStyleFields.findIndex((f) => f.toLowerCase() === 'alignment');
        const sName = (nameIdx !== -1 ? parts[nameIdx] : parts[0] || '').trim().toLowerCase();
        const alignVal = parseInt(alignIdx !== -1 ? parts[alignIdx] : '', 10);
        if (sName && alignVal >= 1 && alignVal <= 9) {
          sourceStyleAlignments[sName] = alignVal;
        }
      }
    }

    const { playResX: srcPlayResX, playResY: srcPlayResY } = extractSourcePlayRes(header);
    scaleX = TARGET_PLAY_RES_X / srcPlayResX;
    scaleY = TARGET_PLAY_RES_Y / srcPlayResY;

    // 1. Replace everything above [V4+ Styles] (or [Events]) with standardized [Script Info] + [Aegisub Project Garbage]
    const stylesIdxInitial = header.findIndex((l) => /^\s*\[v4\+? styles\]/i.test(l));
    const eventsIdxInitial = header.findIndex((l) => /^\s*\[events\]/i.test(l));
    const cutIdx =
      stylesIdxInitial !== -1
        ? stylesIdxInitial
        : eventsIdxInitial !== -1
        ? eventsIdxInitial
        : 0;

    const restOfHeader = stripAegisubGarbageSections(header.slice(cutIdx));
    header = [...STANDARD_ASS_TOP_HEADER, ...restOfHeader];

    // 2. Enforce canonical BURMESE_STYLES & scale any remaining custom source styles to 640x360
    const burmeseStyleByLowerName = new Map<string, string>();
    for (const st of BURMESE_STYLES) {
      const m = st.match(/^\s*Style:\s*([^,]+)/i);
      if (m) burmeseStyleByLowerName.set(m[1].trim().toLowerCase(), st);
    }

    const stylesStartIdx = header.findIndex((l) => /^\s*\[v4\+? styles\]/i.test(l));
    const eventsStartIdx = header.findIndex((l) => /^\s*\[events\]/i.test(l));
    const searchEnd = eventsStartIdx !== -1 ? eventsStartIdx : header.length;

    let styleFormatFields = [
      'Name', 'Fontname', 'Fontsize', 'PrimaryColour', 'SecondaryColour', 'OutlineColour', 'BackColour',
      'Bold', 'Italic', 'Underline', 'StrikeOut', 'ScaleX', 'ScaleY', 'Spacing', 'Angle',
      'BorderStyle', 'Outline', 'Shadow', 'Alignment', 'MarginL', 'MarginR', 'MarginV', 'Encoding',
    ];
    const seenBurmeseStyles = new Set<string>();

    for (let i = Math.max(0, stylesStartIdx); i < searchEnd; i++) {
      const trimmed = header[i].trim();
      if (/^Format\s*:/i.test(trimmed)) {
        styleFormatFields = trimmed.slice(trimmed.indexOf(':') + 1).split(',').map((f) => f.trim());
      } else if (/^Style\s*:/i.test(trimmed)) {
        const m = trimmed.match(/^Style\s*:\s*([^,]+)/i);
        const nameLower = m ? m[1].trim().toLowerCase() : '';
        if (nameLower && burmeseStyleByLowerName.has(nameLower)) {
          header[i] = burmeseStyleByLowerName.get(nameLower)!;
          seenBurmeseStyles.add(nameLower);
        } else if (Math.abs(scaleX - 1) > 1e-4 || Math.abs(scaleY - 1) > 1e-4) {
          header[i] = scaleAssStyleLine(header[i], styleFormatFields, scaleX, scaleY);
        }
      }
    }

    const missingStyles = BURMESE_STYLES.filter((st) => {
      const m = st.match(/^\s*Style:\s*([^,]+)/i);
      const nameLower = m ? m[1].trim().toLowerCase() : '';
      return nameLower.length > 0 && !seenBurmeseStyles.has(nameLower);
    });

    if (missingStyles.length > 0) {
      let insertIdx = -1;
      for (let i = Math.max(0, stylesStartIdx); i < searchEnd; i++) {
        if (/^\s*(Format|Style):/i.test(header[i])) {
          insertIdx = i + 1;
        }
      }

      if (insertIdx !== -1) {
        header.splice(insertIdx, 0, ...missingStyles);
      } else {
        header.push(...missingStyles);
      }
    }
  }

  // 3. Header section (including [Script Info], [V4+ Styles], and [Events] with Format:)
  lines.push(...header);

  // 4. Events lines (prepended watermark events are already 640x360; source events scale cleanly)
  const isSignFlags = sourceEvents.map((event, idx) => {
    const originalEv = parsedData.events[idx];
    return isSignOrTitle(
      event.name,
      event.style,
      originalEv ? originalEv.text : event.text
    );
  });

  const normalizedSourceEvents = applyStyleMapping
    ? sourceEvents.map((event, idx) => {
        const isSign = isSignFlags[idx];
        let normalizedText = normalizeEventTextForTargetPlayRes(event.text, scaleX, scaleY, isSign);
        if (event.type === 'Dialogue' && !isSign) {
          normalizedText = stripLineBreaksForDialogue(normalizedText);
        }
        return {
          ...event,
          style: mapStyleName(event.style, event.name),
          text: normalizedText,
        };
      })
    : sourceEvents;

  // Map original style alignment keys onto mapped style names only if mapped wasn't already defined
  const mergedStyleAlignments: Record<string, number> = { ...sourceStyleAlignments };
  for (const event of sourceEvents) {
    const origKey = (event.style || '').trim().toLowerCase();
    const mappedKey = mapStyleName(event.style, event.name).trim().toLowerCase();
    if (sourceStyleAlignments[origKey] && !mergedStyleAlignments[mappedKey]) {
      mergedStyleAlignments[mappedKey] = sourceStyleAlignments[origKey];
    }
  }

  const postProcessedSourceEvents =
    applyStyleMapping && signTypesetting
      ? applySignTypesettingMode(normalizedSourceEvents, isSignFlags, {
          ...signTypesetting,
          playResX: TARGET_PLAY_RES_X,
          playResY: TARGET_PLAY_RES_Y,
          styleAlignments: mergedStyleAlignments,
        })
      : normalizedSourceEvents;

  const mappedPrependedEvents = applyStyleMapping
    ? prependedEvents.map((ev) => ({
        ...ev,
        style: mapStyleName(ev.style, ev.name),
      }))
    : prependedEvents;

  const eventsToUse = [...mappedPrependedEvents, ...postProcessedSourceEvents];

  for (const event of eventsToUse) {
    const fields = [
      event.layer,
      event.start,
      event.end,
      event.style,
      event.name,
      event.marginL,
      event.marginR,
      event.marginV,
      event.effect,
      event.text,
    ];
    lines.push(`${event.type}: ${fields.join(',')}`);
  }

  // 3. Trailer section if any (strip duplicate [Aegisub Project Garbage] if applyStyleMapping is true)
  const finalTrailer = applyStyleMapping
    ? stripAegisubGarbageSections(parsedData.trailerSection)
    : parsedData.trailerSection;
  if (finalTrailer.length > 0) {
    lines.push('');
    lines.push(...finalTrailer);
  }

  lines.push(''); // Trailing newline
  return lines.join('\n');
}

/**
 * Validates that the translated ASS content is a readable, compliant ASS file
 * and preserves the required event count and timing.
 */
export function validateAss(
  originalParsed: ParsedAssData,
  translatedAssContent: string,
  expectedPrependedCount = 0
): { valid: boolean; errors: string[]; eventCount: number } {
  const errors: string[] = [];

  if (!translatedAssContent || translatedAssContent.trim().length === 0) {
    errors.push('Translated ASS file content is empty.');
    return { valid: false, errors, eventCount: 0 };
  }

  if (!translatedAssContent.includes('[Events]')) {
    errors.push('Missing [Events] section in output ASS file.');
  }

  if (!translatedAssContent.includes('[V4+ Styles]') && !translatedAssContent.includes('[V4 Styles]')) {
    errors.push('Missing styles section in output ASS file.');
  }

  const translatedParsed = parseAss(translatedAssContent);

  if (translatedParsed.events.length !== originalParsed.events.length + expectedPrependedCount) {
    errors.push(
      `Event count mismatch: Expected ${originalParsed.events.length + expectedPrependedCount} events, but output has ${translatedParsed.events.length} events.`
    );
  } else {
    // Check timestamps for each original event (offset by expectedPrependedCount watermark lines)
    for (let i = 0; i < originalParsed.events.length; i++) {
      const orig = originalParsed.events[i];
      const trans = translatedParsed.events[i + expectedPrependedCount];
      if (orig.start !== trans.start || orig.end !== trans.end) {
        errors.push(`Timestamp mismatch at event ${i + 1}: expected ${orig.start}->${orig.end}, got ${trans.start}->${trans.end}`);
        break; // Report first
      }

      const expectedMapped = mapStyleName(orig.style, orig.name);
      const isSignEvent = isSignOrTitle(orig.name, orig.style, orig.text);
      const isAllowedSignOverride =
        isSignEvent && (trans.style === 'Sign_Box' || trans.style === 'Sign_Basic');
      if (trans.style !== orig.style && trans.style !== expectedMapped && !isAllowedSignOverride) {
        errors.push(`Style mismatch at event ${i + 1}: expected ${orig.style} or ${expectedMapped}, got ${trans.style}`);
        break;
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    eventCount: translatedParsed.events.length,
  };
}
